llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Tolfenamic acid, a lipophilic ortho-substituted fenamate NSAID, had absolute oral bioavailability of 55.6% in healthy female volunteers after 400 mg oral vs IV, directly supporting high F for a lipophilic aromatic amide-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Tenoxicam, a lipophilic heteroaromatic enol/amide, was nearly 100% bioavailable orally compared with IV in healthy subjects, supporting high F for a neutral lipophilic heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isoniazid showed 78.4% oral bioavailability in healthy volunteers, and the high assay-transfer score indicates the experimental context strongly applies to the query; this supports high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Bromazepam, a lipophilic heteroaromatic benzodiazepine, had absolute oral bioavailability of 86% in humans, supporting high F for a lipophilic neutral heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Vonoprazan, a lipophilic pyridine-containing drug, was estimated to have 36% oral bioavailability in humans, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Chlorpheniramine, a lipophilic pyridine-containing antihistamine, had oral bioavailability values of 25-50% in humans, all above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Labetalol, a lipophilic aryl-ethanolamine with first-pass metabolism, showed oral bioavailability of 4-17% (mean 9%) in one study, providing limited contradictory evidence that extensive first-pass metabolism could lower F below 20%; however, most labetalol studies report values above 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have high oral bioavailability (F≥20%) based on a large set of high-transfer experimental analogues, mostly lipophilic/heteroaromatic drugs with measured human F values of 25-100%. The only contradictory evidence (labetalol) is variable and mostly above threshold; physicochemical solubility concerns are insufficient to override direct bioavailability data.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the query molecule.",
    "The query's high lipophilicity and low fraction sp3 may cause solubility-limited absorption, which is not directly captured by the analogue data.",
    "Labetalol shows first-pass variability, and the query's amide/thioether may undergo metabolism, but no direct metabolic stability data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

